    isinstance(result[uid], SchemaFileLocation)
    and isinstance(result[uid].target, Path)
    and result[uid].target.is_absolute()
    and result[uid].target == get_target_yaml_path(context, OLD.candidates_map[uid]).resolve()
    and (
        (result[uid].current is None and get_current_yaml_path(context, OLD.candidates_map[uid]) is None)
        or (result[uid].current == (get_current_yaml_path(context, OLD.candidates_map[uid]).resolve()))
    )
    and result[uid].node_type == OLD.candidates_map[uid].resource_type
    for uid in result
))
